class Cache:
    def __init__(self, clock):
        self.clock = clock
        self.values = {}

    def put(self, key, value, ttl):
        self.values[key] = (value, self.clock() + ttl)

    def get(self, key, default=None):
        return self.values.get(key, (default, 0))[0]
